    public function test_json_compare(): void
    {
        // @Arrange
        $one = new TenantConfig(
            uid: 'one',
            tenant: new TenantRef('one'),
            innerLabel: 'one',
            forceMfa: true,
            dynamicRegistrationPolicy: TenantConfigDynamicRegistrationPolicyOptions::OPEN,
            allowRegister: true,
            enableRegisterUsers: true,
            magicLinkEnabled: true,
            requireEmailVerification: true,
            invitationExpiryDays: 1,
            magicLinkExpiryMinutes: 1,
            sessionSsoTtlSeconds: 1,
            refreshTokenTtlSeconds: 1,
            refreshTokenMaxLifetimeSeconds: 1,
            dcrAllowedGrantTypes: 'one',
            dcrAllowedAuthMethods: 'one',
            allowPasswordGrant: true,
            requirePushedAuthorizationRequests: true,
            acrValuesSupported: 'one',
            webauthnEnabled: true,
            webauthnRpId: 'one',
            webauthnRpName: 'one',
            welcomeEmail: 'one',
            registeredEmail: 'one',
            disabledUserEmail: 'one',
            enabledUserEmail: 'one',
            allowRecoverPass: true,
            recoverPassEmail: 'one',
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['tenant']['$ref']);
        $this->assertEquals('one', $json['innerLabel']);
        $this->assertEquals(true, $json['forceMfa']);
        $this->assertEquals(TenantConfigDynamicRegistrationPolicyOptions::OPEN, $json['dynamicRegistrationPolicy']);
        $this->assertEquals(true, $json['allowRegister']);
        $this->assertEquals(true, $json['enableRegisterUsers']);
        $this->assertEquals(true, $json['magicLinkEnabled']);
        $this->assertEquals(true, $json['requireEmailVerification']);
        $this->assertEquals(1, $json['invitationExpiryDays']);
        $this->assertEquals(1, $json['magicLinkExpiryMinutes']);
        $this->assertEquals(1, $json['sessionSsoTtlSeconds']);
        $this->assertEquals(1, $json['refreshTokenTtlSeconds']);
        $this->assertEquals(1, $json['refreshTokenMaxLifetimeSeconds']);
        $this->assertEquals(true, $json['allowPasswordGrant']);
        $this->assertEquals(true, $json['requirePushedAuthorizationRequests']);
        $this->assertEquals(true, $json['webauthnEnabled']);
        $this->assertEquals('one', $json['webauthnRpId']);
        $this->assertEquals('one', $json['webauthnRpName']);
        $this->assertEquals(true, $json['allowRecoverPass']);
        $this->assertEquals(1, $json['version']);
    }
